// G005 放射科RIS系统 - 模拟数据 v3.0.3.31
// 包含：预约记录、医保审核、患者随访、设备维保合同、临床数据同步、影像会诊

import { generateId, formatDate, addDays } from "./simulationStore";

// ==================== 类型定义 ====================

/**
 * 预约记录
 *
 * 表示一次放射检查预约的完整生命周期数据,涵盖登记 → 报到 → 检查 → 取消/旷到
 * 全流程的状态变迁。预约由临床科室发起,经放射科审核后分配到具体设备/检查室。
 *
 * 典型字段语义:
 * - `modality` / `bodyPart` 决定检查室排程与设备资源占用
 * - `priority` 影响排程算法权重(危重 > 紧急 > 普通)
 * - `registrationType` 用于医保/费用结算分流
 */
export interface AppointmentRecord {
  id: string;
  patientId: string;
  patientName: string;
  gender: "男" | "女";
  age: number;
  phone: string;
  idCard: string;
  examItemId: string;
  examItemName: string;
  modality:
    | "CT"
    | "MR"
    | "DR"
    | "DSA"
    | "MG"
    | "PET-CT"
    | "SPECT-CT"
    | "US";
  bodyPart: string;
  examDate: string;
  examTime: string;
  deviceId: string;
  deviceName: string;
  roomId: string;
  roomName: string;
  referringDoctorId: string;
  referringDoctorName: string;
  clinicalDiagnosis: string;
  notes: string;
  status: "待确认" | "已确认" | "已报到" | "已检查" | "已取消" | "旷到";
  priority: "普通" | "紧急" | "危重";
  registrationType: "门诊" | "住院" | "体检" | "急诊";
  createdAt: string;
}

/**
 * 医保审核记录
 *
 * 描述一次医保用药/检查项目的审核流:医生开具 → 提交医保办 → 审核员给出结论。
 * 主要用于增强 CT/MRI 对比剂、抗凝药物等高费用项目的合理性审查,
 * 避免超适应症用药与医保拒付风险。
 */
export interface InsuranceAuditRecord {
  id: string;
  patientName: string;
  patientId: string;
  examType: "CT增强" | "MRI增强" | "DSA手术";
  examItem: string;
  drugName: string;
  drugCategory: "CT对比剂" | "MRI对比剂" | "抗凝药物";
  drugSpec: string;
  restriction: string;
  reason: string;
  submitTime: string;
  submitDept: string;
  urgency: "高" | "中" | "低";
  result?: "通过" | "拒绝" | "补充资料";
  auditor?: string;
  auditTime?: string;
  auditNotes?: string;
}

/**
 * 患者随访记录
 *
 * 描述放射检查后的随访预约与执行情况,常用于:
 * - 早期肺癌筛查低剂量 CT 复查
 * - 肿瘤治疗评估(RECIST)
 * - 对比剂不良反应追踪
 *
 * 通过 `nextFollowUpDate` + `status` 字段驱动提醒工作流。
 */
export interface FollowUpRecord {
  id: string;
  patientId: string;
  patientName: string;
  gender: "男" | "女";
  age: number;
  phone: string;
  examType: string;
  examItemName: string;
  examDate: string;
  followUpType:
    | "对比剂反应"
    | "肿瘤复查"
    | "早期肺癌跟踪"
    | "治疗评估"
    | "术后复查"
    | "介入治疗后评估";
  nextFollowUpDate: string;
  status: "待随访" | "进行中" | "已完成" | "逾期";
  reaction?: "无反应" | "轻度" | "中度" | "重度";
  notes: string;
  referringDoctor: string;
  department: string;
  createdAt: string;
}

/**
 * 设备维保合同
 *
 * 描述影像设备(CT/MR/DR/DSA 等)与第三方维保公司之间的服务合同,
 * 包含合同周期、保修金额、付款状态、服务等级(SLA)、续约历史。
 *
 * `serviceLevel` 影响响应时效:
 * - 标准:48h
 * - 高级:24h
 * - 白金:4h(7×24)
 */
export interface DeviceMaintenanceContract {
  id: string;
  contractNo: string;
  deviceId: string;
  deviceName: string;
  deviceModel: string;
  serialNumber: string;
  company: string;
  contactPerson: string;
  contactTel: string;
  startDate: string;
  endDate: string;
  amount: number;
  paymentStatus: "已付款" | "待付款" | "已逾期";
  coverage: string;
  serviceLevel: "标准" | "高级" | "白金";
  renewHistory: { year: number; amount: number; status: string }[];
  createdAt: string;
}

export interface ClinicalSyncRecord {
  id: string;
  systemName: string;
  systemCode: string;
  recordType: string;
  patientId: string;
  patientName: string;
  dataContent: string;
  syncTime: string;
  status: "同步中" | "已同步" | "失败" | "待同步";
  errorMessage?: string;
  retryCount: number;
  lastRetryTime?: string;
  dataVolume: string;
  sourceDept: string;
}

/**
 * 影像会诊记录
 *
 * 描述一次放射科会诊流:申请科室 → 放射科接诊 → 院内 MDT 或跨院远程会诊。
 * `consultationType` 决定流转路径:
 * - `MDT`:多学科联合诊疗,通常需要提前 24h 召集
 * - `疑难病例`:科内专家会诊
 * - `远程会诊`:通过 DICOM 跨院调阅 + 视频会议
 * - `二次意见`:患者主动申请的院外专家评审
 */
export interface ConsultationRecord {
  id: string;
  consultationNo: string;
  patientName: string;
  patientId: string;
  gender: "男" | "女";
  age: number;
  examType: string;
  examItemName: string;
  requestDept: string;
  requestDoctor: string;
  targetHospital?: string;
  targetDoctor?: string;
  consultationType: "MDT" | "疑难病例" | "远程会诊" | "二次意见";
  urgency: "紧急" | "普通";
  status: "待回复" | "已回复" | "已拒绝" | "进行中" | "已完成";
  requestTime: string;
  completedTime?: string;
  diagnosis?: string;
  opinion?: string;
  remarks?: string;
}

// ==================== 辅助函数：生成相对日期 ====================
function getRelativeDate(daysAgo: number): Date {
  const date = new Date();
  date.setDate(date.getDate() - daysAgo);
  return date;
}

function getRelativeDateStr(daysAgo: number): string {
  return formatDate(getRelativeDate(daysAgo));
}

function randomElement<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

function randomInt(min: number, max: number): number {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

